CREATE TABLE character_wishlist (character_id TEXT NOT NULL REFERENCES characters(id),expansion TEXT NOT NULL,item_id INTEGER NOT NULL REFERENCES item_references(item_id),created_at TEXT NOT NULL,operation_id TEXT NOT NULL UNIQUE,fulfilled_at TEXT,fulfilled_auction_id TEXT,completion_operation TEXT,ignored_auctions_json TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(ignored_auctions_json) AND json_type(ignored_auctions_json)='array'),PRIMARY KEY(character_id,expansion,item_id));
CREATE TABLE wishlist_write_guards (operation_id TEXT PRIMARY KEY,character_id TEXT NOT NULL,actor_id TEXT NOT NULL);
CREATE TRIGGER wishlist_owner_permission BEFORE INSERT ON wishlist_write_guards WHEN NOT EXISTS(SELECT 1 FROM characters c JOIN access_effective_permissions a ON a.user_id=NEW.actor_id WHERE c.id=NEW.character_id AND c.owner_id=NEW.actor_id AND c.kind IN('main','alt') AND c.approved_at IS NOT NULL AND ((json_type(a.permissions_json,'$.overview')='integer' AND json_extract(a.permissions_json,'$.overview')=3) OR (json_type(a.permissions_json,'$.mains')='integer' AND json_extract(a.permissions_json,'$.mains')=3))) BEGIN SELECT RAISE(ABORT,'WISHLIST_OWNER_DENIED'); END;
CREATE TRIGGER wishlist_equipped_insert AFTER INSERT ON character_equipment WHEN NEW.item_id IS NOT NULL BEGIN UPDATE character_wishlist SET fulfilled_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'),fulfilled_auction_id=(SELECT a.id FROM auction_awards w JOIN auctions a ON a.id=w.auction_id JOIN characters c ON c.id=NEW.character_id WHERE w.user_id=c.owner_id AND a.item_id=NEW.item_id AND a.status='closed' AND a.closed_at_ms IS NOT NULL AND a.cancelled_at_ms IS NULL AND a.id NOT IN(SELECT value FROM json_each(character_wishlist.ignored_auctions_json)) ORDER BY a.closed_at_ms DESC,a.id LIMIT 1),completion_operation=NEW.operation_id||':'||operation_id WHERE character_id=NEW.character_id AND item_id=NEW.item_id AND fulfilled_at IS NULL AND EXISTS(SELECT 1 FROM auction_awards w JOIN auctions a ON a.id=w.auction_id JOIN characters c ON c.id=NEW.character_id WHERE w.user_id=c.owner_id AND a.item_id=NEW.item_id AND a.status='closed' AND a.closed_at_ms IS NOT NULL AND a.cancelled_at_ms IS NULL AND a.id NOT IN(SELECT value FROM json_each(character_wishlist.ignored_auctions_json))); INSERT INTO audit(id,actor_id,action,details,created_at) SELECT 'wish-completed-'||completion_operation,NEW.updated_by,'wishlist_item_equipped',json_object('characterId',character_id,'itemId',item_id,'expansion',expansion,'auctionId',fulfilled_auction_id),fulfilled_at FROM character_wishlist WHERE character_id=NEW.character_id AND completion_operation=NEW.operation_id||':'||operation_id ON CONFLICT(id) DO NOTHING; END;
CREATE TRIGGER wishlist_equipped_update AFTER UPDATE OF item_id ON character_equipment WHEN NEW.item_id IS NOT NULL BEGIN UPDATE character_wishlist SET fulfilled_at=strftime('%Y-%m-%dT%H:%M:%fZ','now'),fulfilled_auction_id=(SELECT a.id FROM auction_awards w JOIN auctions a ON a.id=w.auction_id JOIN characters c ON c.id=NEW.character_id WHERE w.user_id=c.owner_id AND a.item_id=NEW.item_id AND a.status='closed' AND a.closed_at_ms IS NOT NULL AND a.cancelled_at_ms IS NULL AND a.id NOT IN(SELECT value FROM json_each(character_wishlist.ignored_auctions_json)) ORDER BY a.closed_at_ms DESC,a.id LIMIT 1),completion_operation=NEW.operation_id||':'||operation_id WHERE character_id=NEW.character_id AND item_id=NEW.item_id AND fulfilled_at IS NULL AND EXISTS(SELECT 1 FROM auction_awards w JOIN auctions a ON a.id=w.auction_id JOIN characters c ON c.id=NEW.character_id WHERE w.user_id=c.owner_id AND a.item_id=NEW.item_id AND a.status='closed' AND a.closed_at_ms IS NOT NULL AND a.cancelled_at_ms IS NULL AND a.id NOT IN(SELECT value FROM json_each(character_wishlist.ignored_auctions_json))); INSERT INTO audit(id,actor_id,action,details,created_at) SELECT 'wish-completed-'||completion_operation,NEW.updated_by,'wishlist_item_equipped',json_object('characterId',character_id,'itemId',item_id,'expansion',expansion,'auctionId',fulfilled_auction_id),fulfilled_at FROM character_wishlist WHERE character_id=NEW.character_id AND completion_operation=NEW.operation_id||':'||operation_id ON CONFLICT(id) DO NOTHING; END;
